// WorkspacesService is the `workspaces` resource group.
type WorkspacesService struct {
	c *Client
}

// AddMember calls POST /workspaces/:id/members (scope: workspaces:write).
func (s *WorkspacesService) AddMember(ctx context.Context, id string, body map[string]any, query map[string]string) (map[string]any, error) {
	return s.c.Do(ctx, "POST", "/workspaces/"+enc(id)+"/members", query, bodyOrEmpty(body))
}

// Create calls POST /workspaces (scope: workspaces:write).
func (s *WorkspacesService) Create(ctx context.Context, body map[string]any, query map[string]string) (map[string]any, error) {
	return s.c.Do(ctx, "POST", "/workspaces", query, bodyOrEmpty(body))
}

// List calls GET /workspaces (scope: workspaces:read).
func (s *WorkspacesService) List(ctx context.Context, query map[string]string) (map[string]any, error) {
	return s.c.Do(ctx, "GET", "/workspaces", query, nil)
}

// Members calls GET /workspaces/:id/members (scope: workspaces:read).
func (s *WorkspacesService) Members(ctx context.Context, id string, query map[string]string) (map[string]any, error) {
	return s.c.Do(ctx, "GET", "/workspaces/"+enc(id)+"/members", query, nil)
}

// RemoveMember calls DELETE /workspaces/:id/members (scope: workspaces:write).
func (s *WorkspacesService) RemoveMember(ctx context.Context, id string, memberId string, query map[string]string) (map[string]any, error) {
	q := map[string]string{}
	for k, v := range query {
		q[k] = v
	}
	q["memberId"] = memberId
	query = q
	return s.c.Do(ctx, "DELETE", "/workspaces/"+enc(id)+"/members", query, nil)
}
